VALUES 
    ('d4444444-4444-4444-4444-444444444444', '33333333-cccc-cccc-cccc-333333333333', 'Convert the Abandoned Plot Near 5th Cross into a Community Park', 'The vacant municipal plot has become an informal dumping ground. This proposal suggests converting it into a low-maintenance public park with walking paths, native trees, children play equipment and seating areas for senior citizens.', 'Proposal', 142, 21, 3, 'Implement an automated smart-stack parking system integrated with existing greenery...', 'Top Draft', 'primary', 56, '5th Cross, Indiranagar', 12.9784, 77.6408, 'Ward 89', '{"tags":["Proposal","Ward"],"tagVariant":["brand","secondary"],"participants":["JD","MK"],"author":"Priya Deshmukh"}', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('e5555555-5555-5555-5555-555555555555', '44444444-dddd-dddd-dddd-444444444444', 'To whom is the higher judiciary accountable?', 'Research and public commentary have raised questions about judicial appointments, the collegium system, and the prevalence of family connections in India higher judiciary. Unlike the Legislature and Executive, which are politically accountable to voters through elections, what mechanisms ensure accountability of the Judiciary?', 'Question', 184, 37, 1, 'Establish a National Judicial Appointments Commission with civil society oversight...', 'New', 'warning', 92, 'New Delhi', 28.6139, 77.2090, 'National', '{"tags":["Question","Judiciary"],"tagVariant":["brand","secondary"],"participants":["RS","MK"],"author":"Vikram Joshi"}', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('f6666666-6666-6666-6666-666666666666', '22222222-bbbb-bbbb-bbbb-222222222222', 'Did the Supreme Court action against the NCERT chapter on judicial corruption strike the right balance?', 'The Supreme Court intervention regarding an NCERT chapter discussing judicial corruption has revived an important constitutional debate. Should courts be able to restrict educational material concerning the judiciary?', 'Debate', 624, 52, 0, NULL, NULL, NULL, 184, 'New Delhi', 28.6139, 77.2090, 'National', '{"tags":["Debate","Judiciary","India"],"tagVariant":["error","secondary","brand"],"participants":["RS","NP"],"author":"Rajan Malhotra"}', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);